import { useEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import type { Project, Session } from '../types';
import { CUPPET_LOGO_URL } from './brand';

const SIDEBAR_WIDTH_KEY = 'cuppet.desktop.sidebar-width';
const SIDEBAR_COLLAPSED_KEY = 'cuppet.desktop.sidebar-collapsed';
const MIN_WIDTH = 220;
const MAX_WIDTH = 420;
const DEFAULT_WIDTH = 286;
const COLLAPSED_WIDTH = 42;
const MAX_VISIBLE_CHATS = 5;

type Props = {
  projects: Project[];
  sessions: Session[];
  generalSessions: Session[];
  activeSessionId: string | null;
  unreadSessionIds?: ReadonlySet<string>;
  selectedProjectId: string | null;
  collapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  onNewChat: () => void;
  onNewProjectChat: (projectId: string) => void;
  onSearch: () => void;
  onRemote: () => void;
  onSettings: () => void;
  onAddProject: () => void;
  onProject: (projectId: string) => void | Promise<void>;
  onSession: (sessionId: string) => void | Promise<void>;
  onRenameProject: (project: Project, name: string) => void | Promise<void>;
  onRemoveProject: (project: Project) => void | Promise<void>;
  onArchiveSession: (session: Session) => void | Promise<void>;
  onDeleteSession: (session: Session) => void | Promise<void>;
  onOpenProjectGraph?: (projectId: string) => void;
  isGraphOpen?: boolean;
};

type RenameTarget =
  | { kind: 'project'; project: Project }
  | { kind: 'session'; session: Session };

export function Sidebar(props: Props) {
  const [width, setWidth] = useState(() => clamp(Number(localStorage.getItem(SIDEBAR_WIDTH_KEY)) || DEFAULT_WIDTH));
  const [uncontrolledCollapsed, setUncontrolledCollapsed] = useState(() => localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === '1');
  const collapsed = props.collapsed ?? uncontrolledCollapsed;
  const setCollapsed = (value: boolean | ((current: boolean) => boolean)) => {
    const next = typeof value === 'function' ? value(props.collapsed ?? uncontrolledCollapsed) : value;
    if (props.onCollapsedChange) props.onCollapsedChange(next);
    else setUncontrolledCollapsed(next);
  };
  const [menu, setMenu] = useState<{ kind: 'project' | 'session'; id: string; x: number; y: number } | null>(null);
  const [renameTarget, setRenameTarget] = useState<RenameTarget | null>(null);
  const [renameValue, setRenameValue] = useState('');
  const [renameError, setRenameError] = useState('');
  const [renameSaving, setRenameSaving] = useState(false);
  const [deleteSession, setDeleteSession] = useState<Session | null>(null);
  const [deleteError, setDeleteError] = useState('');
  const [deleting, setDeleting] = useState(false);
  const [titleOverrides, setTitleOverrides] = useState<Record<string, string>>({});
  const [expandedChatGroups, setExpandedChatGroups] = useState<Set<string>>(() => new Set());
  const dragging = useRef(false);
  const isMac = window.cuppet.native.platform === 'darwin';
  const sidebarCollapsed = collapsed;

  useEffect(() => {
    const onMove = (event: PointerEvent) => {
      if (!dragging.current) return;
      setWidth(clamp(event.clientX));
    };
    const onUp = (event: PointerEvent) => {
      if (!dragging.current) return;
      dragging.current = false;
      document.body.classList.remove('sidebar-resizing');
      localStorage.setItem(SIDEBAR_WIDTH_KEY, String(width));
      if (event.clientX < MIN_WIDTH / 2) setCollapsed(true);
    };
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
    };
  }, [width, setCollapsed]);

  useEffect(() => {
    localStorage.setItem(SIDEBAR_COLLAPSED_KEY, collapsed ? '1' : '0');
    if (props.onCollapsedChange) props.onCollapsedChange(collapsed);
  }, [collapsed, props]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((isMac ? !event.metaKey : !(event.ctrlKey || event.metaKey)) || !event.altKey || event.key.toLowerCase() !== 's') return;
      event.preventDefault();
      setCollapsed((current) => !current);
      setMenu(null);
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [isMac, setCollapsed]);

  useEffect(() => {
    const close = () => setMenu(null);
    window.addEventListener('blur', close);
    document.addEventListener('pointerdown', close);
    return () => {
      window.removeEventListener('blur', close);
      document.removeEventListener('pointerdown', close);
    };
  }, []);

  useEffect(() => {
    setTitleOverrides((current) => {
      let changed = false;
      const next = { ...current };
      for (const session of props.sessions) {
        if (next[session.id] && next[session.id] === session.title) {
          delete next[session.id];
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [props.sessions]);

  const sessionsByProject = useMemo(() => {
    const map = new Map<string, Session[]>();
    for (const session of props.sessions) {
      if (!session.projectId) continue;
      const list = map.get(session.projectId) ?? [];
      list.push(session);
      map.set(session.projectId, list);
    }
    return map;
  }, [props.sessions]);

  useEffect(() => {
    if (!props.activeSessionId) return;
    const projectSession = props.sessions.find((session) => session.id === props.activeSessionId);
    const groupKey = projectSession?.projectId ?? null;
    if (!groupKey) return;
    const groupSessions = sessionsByProject.get(groupKey) ?? [];
    if (groupSessions.findIndex((session) => session.id === props.activeSessionId) < MAX_VISIBLE_CHATS) return;
    setExpandedChatGroups((current) => {
      if (current.has(groupKey)) return current;
      const next = new Set(current);
      next.add(groupKey);
      return next;
    });
  }, [props.activeSessionId, props.sessions, props.generalSessions, sessionsByProject]);

  const toggleChatGroup = (groupKey: string) => {
    setExpandedChatGroups((current) => {
      const next = new Set(current);
      if (next.has(groupKey)) next.delete(groupKey);
      else next.add(groupKey);
      return next;
    });
  };

  const [hoveredSession, setHoveredSession] = useState<{ id: string; title: string; x: number; y: number; isBottom: boolean } | null>(null);
  const hoverTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleSessionHoverStart = (session: Session, displayTitle: string, event: React.MouseEvent) => {
    if (hoverTimer.current) clearTimeout(hoverTimer.current);
    setHoveredSession(null);
    const rect = event.currentTarget.getBoundingClientRect();
    const isBottom = rect.bottom + 60 > window.innerHeight;
    hoverTimer.current = setTimeout(() => {
      setHoveredSession({
        id: session.id,
        title: displayTitle,
        x: rect.left,
        y: isBottom ? rect.top : rect.bottom,
        isBottom,
      });
    }, 500);
  };

  const handleSessionHoverEnd = () => {
    if (hoverTimer.current) {
      clearTimeout(hoverTimer.current);
      hoverTimer.current = null;
    }
    setHoveredSession(null);
  };

  useEffect(() => {
    return () => {
      if (hoverTimer.current) clearTimeout(hoverTimer.current);
    };
  }, []);

  const openMenu = (event: React.MouseEvent, kind: 'project' | 'session', id: string) => {
    event.preventDefault();
    event.stopPropagation();
    handleSessionHoverEnd();
    setMenu({ kind, id, x: Math.min(event.clientX || event.currentTarget.getBoundingClientRect().right, window.innerWidth - 200), y: Math.min(event.clientY || event.currentTarget.getBoundingClientRect().bottom, window.innerHeight - 180) });
  };

  const beginRenameProject = (project: Project) => {
    handleSessionHoverEnd();
    setMenu(null);
    setRenameTarget({ kind: 'project', project });
    setRenameValue(project.name || '');
    setRenameError('');
    setRenameSaving(false);
  };

  const beginRenameSession = (session: Session) => {
    handleSessionHoverEnd();
    setMenu(null);
    setRenameTarget({ kind: 'session', session });
    setRenameValue(titleOverrides[session.id] || session.title || 'New chat');
    setRenameError('');
    setRenameSaving(false);
  };

  const closeRename = () => {
    if (renameSaving) return;
    setRenameTarget(null);
    setRenameError('');
  };

  const saveRename = async () => {
    if (!renameTarget || renameSaving) return;
    const value = renameValue.trim();
    if (!value) return;

    if (renameTarget.kind === 'project') {
      if (value === renameTarget.project.name) {
        setRenameTarget(null);
        return;
      }
      setRenameError('');
      setRenameSaving(true);
      try {
        await props.onRenameProject(renameTarget.project, value);
        setRenameTarget(null);
      } catch (error) {
        setRenameError(error instanceof Error ? error.message : String(error ?? 'Unable to rename project.'));
      } finally {
        setRenameSaving(false);
      }
      return;
    }

    const session = renameTarget.session;
    if (value === (titleOverrides[session.id] || session.title || 'New chat')) {
      setRenameTarget(null);
      return;
    }
    setRenameError('');
    setRenameSaving(true);
    try {
      await window.cuppet.sessions.rename(session.id, value);
      setTitleOverrides((current) => ({ ...current, [session.id]: value }));
      if (props.activeSessionId === session.id) await props.onSession(session.id);
      setRenameTarget(null);
    } catch (error) {
      setRenameError(error instanceof Error ? error.message : String(error ?? 'Unable to rename chat.'));
    } finally {
      setRenameSaving(false);
    }
  };

  const beginDeleteSession = (session: Session) => {
    handleSessionHoverEnd();
    setMenu(null);
    setDeleteSession(session);
    setDeleteError('');
    setDeleting(false);
  };

  const confirmDeleteSession = async () => {
    if (!deleteSession || deleting) return;
    setDeleting(true);
    setDeleteError('');
    try {
      await props.onDeleteSession(deleteSession);
      setDeleteSession(null);
    } catch (error) {
      setDeleteError(error instanceof Error ? error.message : String(error ?? 'Unable to delete chat.'));
    } finally {
      setDeleting(false);
    }
  };

  const toggleSidebar = () => {
    handleSessionHoverEnd();
    setCollapsed((current) => !current);
    setMenu(null);
  };

  const sidebarWidth = sidebarCollapsed ? COLLAPSED_WIDTH : width;

  return (
    <aside
      className={`sidebar react-sidebar${sidebarCollapsed ? ' collapsed' : ''}`}
      style={{ width: sidebarWidth, minWidth: sidebarWidth }}
      onPointerLeave={handleSessionHoverEnd}
    >
      <button
        type="button"
        className="sidebar-toggle-button"
        aria-label={collapsed ? 'Show sidebar' : 'Hide sidebar'}
        title={`${collapsed ? 'Show' : 'Hide'} sidebar (${isMac ? '⌥⌘S' : 'Ctrl+Alt+S'})`}
        onClick={toggleSidebar}
      >
        <svg viewBox="0 0 18 18" fill="none" aria-hidden="true">
          <rect x="2.5" y="3" width="13" height="12" rx="2.2" stroke="currentColor" strokeWidth="1.25" />
          <path d="M7 3v12" stroke="currentColor" strokeWidth="1.25" />
        </svg>
      </button>

      {sidebarCollapsed && (
        <>
          <div className="sidebar-collapsed-brand" title="Cuppet"><img src={CUPPET_LOGO_URL} alt="" aria-hidden="true" /></div>
          <nav className="primary-nav sidebar-compact-nav" aria-label="Primary">
            <button type="button" className="nav-button sidebar-compact-action" aria-label="New chat" title="New chat" onClick={props.onNewChat} />
            <button type="button" className="nav-button sidebar-compact-action" aria-label="Search" title="Search" onClick={props.onSearch} />
            <button type="button" className="nav-button sidebar-compact-action" aria-label="Agents" title="Agents" disabled />
            <button type="button" className="nav-button sidebar-compact-action" aria-label="Remote" title="Remote" onClick={props.onRemote} />
          </nav>
          <div className="sidebar-bottom sidebar-compact-bottom">
            <button type="button" className="ghost-button sidebar-compact-action" aria-label="Settings" title="Settings" onClick={props.onSettings} />
          </div>
        </>
      )}

      {!sidebarCollapsed && <>
        <div className="sidebar-top">
          <div className="brand-row">
            <img className="brand-mark" src={CUPPET_LOGO_URL} alt="" aria-hidden="true" />
            <div className="brand-title">Cuppet</div>
          </div>
          <nav className="primary-nav" aria-label="Primary">
            <button type="button" className="nav-button" onClick={props.onNewChat}>New chat</button>
            <button type="button" className="nav-button" onClick={props.onSearch}>Search</button>
            <button type="button" className="nav-button" disabled>Agents</button>
            <button type="button" className="nav-button" onClick={props.onRemote}>Remote</button>
          </nav>
        </div>

        <div className="projects-header">
          <span>Projects</span>
          <button type="button" className="project-add-button" aria-label="Add project" title="Add project" onClick={props.onAddProject}>+</button>
        </div>

        <div className="project-list" aria-label="Projects and conversations" onScroll={handleSessionHoverEnd}>
          {props.projects.map((project) => {
            const projectActive = props.activeSessionId === null && props.selectedProjectId === project.id;
            const projectSessions = sessionsByProject.get(project.id) ?? [];
            const chatsExpanded = expandedChatGroups.has(project.id);
            const visibleProjectSessions = chatsExpanded ? projectSessions : projectSessions.slice(0, MAX_VISIBLE_CHATS);
            const projectMenuOpen = menu?.kind === 'project' && menu.id === project.id;
            return (
              <section className="project-group" key={project.id}>
                <div className={`project-row${projectActive ? ' active' : ''}${projectMenuOpen ? ' menu-open' : ''}`} onContextMenu={(event) => openMenu(event, 'project', project.id)}>
                  <button
                    type="button"
                    className="project-button"
                    aria-current={projectActive ? 'page' : undefined}
                    title={projectMetadata(project)}
                    onClick={() => void props.onProject(project.id)}
                  >
                    <span className="project-name">{project.name}</span>
                  </button>
                  <button
                    type="button"
                    className="project-new-chat-button"
                    aria-label={`New chat in ${project.name}`}
                    title={`New chat in ${project.name}`}
                    onClick={(event) => {
                      event.stopPropagation();
                      props.onNewProjectChat(project.id);
                    }}
                  >+</button>
                  <button type="button" className="project-menu-button" aria-label={`Actions for ${project.name}`} title={`Actions for ${project.name}`} onClick={(event) => openMenu(event, 'project', project.id)}>⋯</button>
                </div>
                {visibleProjectSessions.map((session) => (
                  <SessionRow
                    key={session.id}
                    session={session}
                    title={titleOverrides[session.id]}
                    active={props.activeSessionId === session.id}
                    unread={props.unreadSessionIds?.has(session.id)}
                    menuOpen={menu?.kind === 'session' && menu.id === session.id}
                    onOpen={props.onSession}
                    onMenu={openMenu}
                    onHoverStart={handleSessionHoverStart}
                    onHoverEnd={handleSessionHoverEnd}
                  />
                ))}
                {projectSessions.length > MAX_VISIBLE_CHATS && (
                  <button
                    type="button"
                    className="session-show-more"
                    aria-expanded={chatsExpanded}
                    onClick={() => toggleChatGroup(project.id)}
                  >{chatsExpanded ? 'Show less' : 'Show more'}</button>
                )}
              </section>
            );
          })}

          {props.generalSessions.length > 0 && (
            <section className="project-group general-group">
              <div className="general-label">General</div>
              {props.generalSessions.map((session) => (
                <SessionRow
                  key={session.id}
                  session={session}
                  title={titleOverrides[session.id]}
                  active={props.activeSessionId === session.id}
                  unread={props.unreadSessionIds?.has(session.id)}
                  menuOpen={menu?.kind === 'session' && menu.id === session.id}
                  onOpen={props.onSession}
                  onMenu={openMenu}
                  onHoverStart={handleSessionHoverStart}
                  onHoverEnd={handleSessionHoverEnd}
                />
              ))}
            </section>
          )}

          {!props.projects.length && !props.generalSessions.length && (
            <div className="sidebar-empty">No projects yet. Add a folder or clone a repository.</div>
          )}
        </div>

        <div className="sidebar-bottom">
          <button type="button" className="ghost-button full" onClick={props.onSettings}>Settings</button>
        </div>

        <div
          className="sidebar-resizer"
          role="separator"
          aria-label="Resize sidebar"
          aria-orientation="vertical"
          aria-valuemin={MIN_WIDTH}
          aria-valuemax={MAX_WIDTH}
          tabIndex={0}
          onPointerDown={(event) => {
            event.preventDefault();
            dragging.current = true;
            document.body.classList.add('sidebar-resizing');
            event.currentTarget.setPointerCapture?.(event.pointerId);
          }}
          onDoubleClick={() => {
            setWidth(DEFAULT_WIDTH);
            localStorage.setItem(SIDEBAR_WIDTH_KEY, String(DEFAULT_WIDTH));
          }}
          onKeyDown={(event) => {
            if (event.key === 'ArrowLeft') setWidth((value) => clamp(value - 10));
            if (event.key === 'ArrowRight') setWidth((value) => clamp(value + 10));
          }}
        />

        {menu && (
          <ContextMenu
            {...props}
            menu={menu}
            onClose={() => setMenu(null)}
            onStartRenameProject={beginRenameProject}
            onStartRenameSession={beginRenameSession}
            onStartDeleteSession={beginDeleteSession}
          />
        )}
      </>}

      {renameTarget && createPortal(
        <div className="sidebar-rename-backdrop" onPointerDown={closeRename}>
          <form
            className="sidebar-rename-dialog"
            role="dialog"
            aria-modal="true"
            aria-labelledby="sidebar-rename-title"
            onPointerDown={(event) => event.stopPropagation()}
            onSubmit={(event) => {
              event.preventDefault();
              void saveRename();
            }}
          >
            <label id="sidebar-rename-title" htmlFor="sidebar-rename-input">
              {renameTarget.kind === 'project' ? 'Rename project' : 'Rename chat'}
            </label>
            <input
              id="sidebar-rename-input"
              autoFocus
              value={renameValue}
              maxLength={160}
              disabled={renameSaving}
              onChange={(event) => setRenameValue(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === 'Escape') {
                  event.preventDefault();
                  closeRename();
                }
              }}
            />
            {renameError && <div className="sidebar-rename-error" role="alert">{renameError}</div>}
            <div className="sidebar-rename-actions">
              <button type="button" onClick={closeRename} disabled={renameSaving}>Cancel</button>
              <button type="submit" disabled={renameSaving || !renameValue.trim()}>{renameSaving ? 'Saving…' : 'Save'}</button>
            </div>
          </form>
        </div>,
        document.body,
      )}

      {deleteSession && createPortal(
        <div className="sidebar-delete-backdrop" onPointerDown={() => !deleting && setDeleteSession(null)}>
          <div
            className="sidebar-delete-dialog"
            role="alertdialog"
            aria-modal="true"
            aria-labelledby="sidebar-chat-delete-title"
            aria-describedby="sidebar-chat-delete-desc"
            onPointerDown={(event) => event.stopPropagation()}
            onKeyDown={(event) => {
              if (event.key === 'Escape' && !deleting) {
                event.preventDefault();
                setDeleteSession(null);
              }
            }}
          >
            <div className="sidebar-delete-header">
              <h3 id="sidebar-chat-delete-title" className="sidebar-delete-title">Delete chat?</h3>
              <p id="sidebar-chat-delete-desc" className="sidebar-delete-desc">
                Are you sure you want to delete <span className="sidebar-delete-name">“{titleOverrides[deleteSession.id] || deleteSession.title || 'New chat'}”</span>?
                <span className="sidebar-delete-subtext">Chats deleted from the sidebar remain recoverable for 7 days in Settings.</span>
              </p>
            </div>
            {deleteError && <div className="sidebar-delete-error" role="alert">{deleteError}</div>}
            <div className="sidebar-delete-actions">
              <button
                type="button"
                className="sidebar-cancel-button"
                onClick={() => setDeleteSession(null)}
                disabled={deleting}
              >
                Cancel
              </button>
              <button
                type="button"
                autoFocus
                className="sidebar-danger-button"
                disabled={deleting}
                onClick={() => void confirmDeleteSession()}
              >
                {deleting ? 'Deleting…' : 'Delete chat'}
              </button>
            </div>
          </div>
        </div>,
        document.body,
      )}

      {hoveredSession && (
        <div
          className="session-title-tooltip"
          role="tooltip"
          style={{
            left: Math.max(10, Math.min(hoveredSession.x, window.innerWidth - 320)),
            ...(hoveredSession.isBottom
              ? { bottom: window.innerHeight - hoveredSession.y + 4 }
              : { top: hoveredSession.y + 4 }),
          }}
        >
          {hoveredSession.title}
        </div>
      )}
    </aside>
  );
}

function SessionRow({
  session,
  title,
  active,
  unread = false,
  menuOpen,
  onOpen,
  onMenu,
  onHoverStart,
  onHoverEnd,
}: {
  session: Session;
  title?: string;
  active: boolean;
  unread?: boolean;
  menuOpen?: boolean;
  onOpen: (id: string) => void | Promise<void>;
  onMenu: (event: React.MouseEvent, kind: 'project' | 'session', id: string) => void;
  onHoverStart: (session: Session, displayTitle: string, event: React.MouseEvent) => void;
  onHoverEnd: () => void;
}) {
  const displayTitle = title || session.title || 'New chat';
  return (
    <div className={`session-row${menuOpen ? ' menu-open' : ''}`} onContextMenu={(event) => onMenu(event, 'session', session.id)}>
      <button
        type="button"
        className={`session-item${active ? ' active' : ''}`}
        aria-current={active ? 'page' : undefined}
        onClick={() => {
          onHoverEnd();
          void onOpen(session.id);
        }}
        onMouseEnter={(event) => onHoverStart(session, displayTitle, event)}
        onMouseLeave={onHoverEnd}
        onPointerDown={onHoverEnd}
      >
        {unread && <span className="session-unread-marker" role="img" aria-label="Unread agent work" title="Unread agent work" />}
        <div className="session-title">{displayTitle}</div>
        <div className="session-meta">{relativeTime(session.updatedAt)}</div>
      </button>
      <button
        type="button"
        className="session-menu-button"
        aria-label={`Actions for ${displayTitle}`}
        onClick={(event) => {
          onHoverEnd();
          onMenu(event, 'session', session.id);
        }}
      >⋯</button>
    </div>
  );
}

function ContextMenu(props: Props & {
  menu: { kind: 'project' | 'session'; id: string; x: number; y: number };
  onClose: () => void;
  onStartRenameProject: (project: Project) => void;
  onStartRenameSession: (session: Session) => void;
  onStartDeleteSession: (session: Session) => void;
}) {
  const { menu, onClose, projects, sessions, onRemoveProject, onArchiveSession, onStartRenameProject, onStartRenameSession, onStartDeleteSession, onOpenProjectGraph } = props;
  const project = menu.kind === 'project' ? projects.find((item) => item.id === menu.id) : null;
  const session = menu.kind === 'session' ? sessions.find((item) => item.id === menu.id) : null;
  const run = (action: () => void | Promise<void>) => {
    onClose();
    void action();
  };

  return createPortal(
    <div className="nav-context-menu react-context-menu" role="menu" style={{ left: menu.x, top: menu.y }} onPointerDown={(event) => event.stopPropagation()}>
      {project && <>
        {onOpenProjectGraph && (
          <button type="button" onClick={() => run(() => onOpenProjectGraph(project.id))}>
            {props.isGraphOpen && props.selectedProjectId === project.id ? 'Hide project graph' : 'Show project graph'}
          </button>
        )}
        <button type="button" onClick={() => onStartRenameProject(project)}>Rename project</button>
        <hr />
        <button type="button" className="danger" onClick={() => run(() => onRemoveProject(project))}>Remove project</button>
      </>}
      {session && <>
        <button type="button" onClick={() => onStartRenameSession(session)}>Rename chat</button>
        <button type="button" onClick={() => run(() => onArchiveSession(session))}>Archive chat</button>
        <hr />
        <button type="button" className="danger" onClick={() => onStartDeleteSession(session)}>Delete chat…</button>
      </>}
    </div>,
    document.body,
  );
}

function clamp(value: number) {
  return Math.min(MAX_WIDTH, Math.max(MIN_WIDTH, Math.round(value)));
}

function projectMetadata(project: Project) {
  if (project.missing) return 'Folder missing';
  return [project.branch, project.dirty ? 'modified' : null].filter(Boolean).join(' · ') || 'Local folder';
}

function relativeTime(timestamp?: number) {
  if (!timestamp) return '';
  const seconds = Math.max(0, Math.floor((Date.now() - timestamp) / 1000));
  if (seconds < 60) return 'now';
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes}m`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h`;
  const days = Math.floor(hours / 24);
  if (days < 30) return `${days}d`;
  const months = Math.floor(days / 30.4375);
  if (months < 12) return `${Math.max(1, months)}M`;
  const years = Math.floor(days / 365.25);
  return `${Math.max(1, years)}Y`;
}
