import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

type EditedFile = {
  path: string;
  tool?: string;
  updatedAt?: number;
  mutationId?: string | null;
  executionId?: string | null;
};

type GraphStats = {
  files?: number;
  modules?: number;
  symbols?: number;
  edges?: number;
  progress?: { discovered?: number; indexed?: number; skipped?: number; complete?: boolean };
};

type MemoryGraphSnapshot = {
  available?: boolean;
  reason?: string;
  root?: string;
  graph?: GraphStats;
  files?: string[];
  editedFiles?: EditedFile[];
};

type GraphNode = {
  id: string;
  path: string;
  label: string;
  kind: 'file' | 'group';
  x: number;
  y: number;
  childCount?: number;
  expanded?: boolean;
  editedAt: number;
  tool?: string;
};

type GraphEdge = { from: string; to: string };

type Props = {
  sessionId: string | null;
  projectName?: string | null;
  running?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
};

const MAX_GRAPH_FILES = 180;
const ACTIVE_EDIT_MS = 12_000;
const MIN_GRAPH_ZOOM = 0.2;
const MAX_GRAPH_ZOOM = 8.0;
const NODE_CLICK_RADIUS = 13;
const DRAG_THRESHOLD = 5;
const ROOT_NODE_PATH = '__cuppet_root__';
const GRAPH_COLUMN_GAP = 172;
const GRAPH_ROW_GAP = 30;
const GRAPH_LABEL_WIDTH = 148;

export function TstMemorySidebar({ sessionId, projectName, running = false, open: openProp, onOpenChange }: Props) {
  const [snapshot, setSnapshot] = useState<MemoryGraphSnapshot | null>(null);
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);
  const open = openProp ?? uncontrolledOpen;
  const setOpen = useCallback((value: boolean | ((current: boolean) => boolean)) => {
    const next = typeof value === 'function' ? value(openProp ?? uncontrolledOpen) : value;
    if (onOpenChange) onOpenChange(next);
    else setUncontrolledOpen(next);
  }, [onOpenChange, openProp, uncontrolledOpen]);
  const [loading, setLoading] = useState(false);
  const [selectedPath, setSelectedPath] = useState<string | null>(null);

  const refresh = useCallback(async (quiet = false) => {
    if (!sessionId) {
      setSnapshot(null);
      return;
    }
    if (!quiet) setLoading(true);
    try {
      const graph = await window.cuppet.cognitive.memoryGraph(sessionId).catch((error: unknown) => ({ available: false, reason: cleanError(error), files: [], editedFiles: [] }));
      setSnapshot(graph && typeof graph === 'object' ? graph : { available: false, reason: 'TST graph returned an invalid snapshot', files: [], editedFiles: [] });
    } finally {
      if (!quiet) setLoading(false);
    }
  }, [sessionId]);

  useEffect(() => {
    if (!open) return;
    setSelectedPath(null);
    void refresh();
  }, [open, refresh]);

  useEffect(() => {
    if (!sessionId || !open) return;
    const interval = window.setInterval(() => void refresh(true), running ? 1800 : 7500);
    return () => window.clearInterval(interval);
  }, [open, refresh, running, sessionId]);

  useEffect(() => {
    if (!sessionId || !open) return;
    let timer: number | null = null;
    const unsubscribe = window.cuppet.onEvent((event: any) => {
      if (!event || (event.sessionId && event.sessionId !== sessionId)) return;
      const type = String(event.type ?? '');
      if (!type.includes('tool') && !type.includes('mutation') && !type.includes('graph') && type !== 'message.completed') return;
      if (timer) window.clearTimeout(timer);
      timer = window.setTimeout(() => void refresh(true), 180);
    });
    return () => {
      if (timer) window.clearTimeout(timer);
      unsubscribe?.();
    };
  }, [open, refresh, sessionId]);

  if (!sessionId || !open) return null;

  const files = Array.isArray(snapshot?.files) ? snapshot!.files! : [];
  const edits = Array.isArray(snapshot?.editedFiles) ? snapshot!.editedFiles! : [];
  const recent = [...edits].sort((a, b) => Number(b.updatedAt ?? 0) - Number(a.updatedAt ?? 0)).slice(0, 5);
  const selected = selectedPath && selectedPath !== ROOT_NODE_PATH ? edits.find((item) => normalizePath(item.path) === normalizePath(selectedPath)) : null;
  const indexing = snapshot?.graph?.progress;

  return (
    <aside className="memory-sidebar" aria-label="TST memory graph">
      <header className="memory-sidebar-header">
        <div className="memory-sidebar-title-wrap">
          <div className="memory-sidebar-icon"><MemoryIcon /></div>
          <div>
            <div className="memory-sidebar-title">TST memory</div>
            <div className="memory-sidebar-subtitle">{projectName || 'Project graph'}</div>
          </div>
        </div>
        <div className="memory-sidebar-actions">
          <button type="button" className="memory-icon-button" title="Refresh memory graph" aria-label="Refresh memory graph" onClick={() => void refresh()}>
            <RefreshIcon spinning={loading} />
          </button>
          <button type="button" className="memory-icon-button" title="Hide memory sidebar" aria-label="Hide memory sidebar" onClick={() => setOpen(false)}>
            <CloseIcon />
          </button>
        </div>
      </header>

      <div className="memory-sidebar-stats" aria-label="Memory graph status">
        <span><strong>{snapshot?.graph?.files ?? files.length}</strong> files</span>
        <span><strong>{snapshot?.graph?.symbols ?? 0}</strong> symbols</span>
        <span className={indexing?.complete ? 'ready' : 'indexing'}>{indexing?.complete ? 'Indexed' : 'Indexing'}</span>
      </div>

      <div className="memory-graph-stage">
        <button
          type="button"
          className="memory-floating-close-button"
          aria-label="Close project graph"
          title="Close project graph"
          onClick={() => setOpen(false)}
        >
          ×
        </button>
        {snapshot?.available === false && !edits.length ? (
          <div className="memory-graph-empty">
            <MemoryIcon />
            <strong>TST graph unavailable</strong>
            <span>{snapshot.reason || 'Open a project-bound chat to visualize memory.'}</span>
            <button type="button" className="memory-dismiss-btn" onClick={() => setOpen(false)}>Close graph</button>
          </div>
        ) : files.length || edits.length ? (
          <MemoryGraphCanvas files={files.length > 0 ? files : edits.map((e) => e.path)} edits={edits} selectedPath={selectedPath} onSelect={setSelectedPath} />
        ) : (
          <div className="memory-graph-empty">
            <MemoryIcon />
            <strong>{loading ? 'Loading project memory…' : 'Building project memory…'}</strong>
            <span>Nodes appear as TST indexes files and Cuppet touches the workspace.</span>
            <button type="button" className="memory-dismiss-btn" onClick={() => setOpen(false)}>Close graph</button>
          </div>
        )}
        <div className="memory-graph-legend" aria-hidden="true">
          <span><i className="memory-dot file" />file</span>
          <span><i className="memory-dot edited" />edited</span>
          <span><i className="memory-dot group" />folder</span>
        </div>
      </div>

      {selectedPath && (
        <div className="memory-node-inspector">
          <div className="memory-inspector-label">Selected node</div>
          <strong title={displayGraphPath(selectedPath)}>{displayGraphPath(selectedPath)}</strong>
          <div className="memory-inspector-meta">
            {selected?.updatedAt ? <span>Edited {relativeTime(selected.updatedAt)}</span> : <span>Indexed by TST</span>}
            {selected?.tool ? <span>{humanTool(selected.tool)}</span> : null}
          </div>
        </div>
      )}

      <section className="memory-activity-section">
        <div className="memory-section-heading">
          <span>Workspace activity</span>
          {running ? <span className="memory-live"><i /> live</span> : null}
        </div>
        {recent.length ? (
          <div className="memory-activity-list">
            {recent.map((item, index) => (
              <button type="button" key={`${item.mutationId ?? item.path}:${index}`} className="memory-activity-item" onClick={() => setSelectedPath(item.path)}>
                <span className="memory-activity-pulse" />
                <span className="memory-activity-copy">
                  <strong title={item.path}>{leafName(item.path)}</strong>
                  <small>{humanTool(item.tool || 'edit')} · {relativeTime(item.updatedAt ?? 0)}</small>
                </span>
              </button>
            ))}
          </div>
        ) : (
          <div className="memory-activity-empty">No file mutations in this chat yet.</div>
        )}
      </section>
    </aside>
  );
}

function MemoryGraphCanvas({ files, edits, selectedPath, onSelect }: { files: string[]; edits: EditedFile[]; selectedPath: string | null; onSelect: (path: string | null) => void }) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [expandedPaths, setExpandedPaths] = useState(() => new Set([ROOT_NODE_PATH]));
  const scene = useMemo(() => buildScene(files, edits, expandedPaths), [files, edits, expandedPaths]);
  const sceneRef = useRef(scene);
  const selectedRef = useRef(selectedPath);
  const zoomRef = useRef(1);
  const [zoomDisplay, setZoomDisplay] = useState(100);
  const panRef = useRef({ x: 0, y: 0 });
  const customPositionsRef = useRef<Map<string, { x: number; y: number }>>(new Map());
  const draggedNodeRef = useRef<GraphNode | null>(null);
  const hoveredNodeIdRef = useRef<string | null>(null);
  const pointerRef = useRef<{
    x: number;
    y: number;
    startX: number;
    startY: number;
    dragging: boolean;
    moved: boolean;
    mode: 'node' | 'pan';
    node: GraphNode | null;
  }>({
    x: 0,
    y: 0,
    startX: 0,
    startY: 0,
    dragging: false,
    moved: false,
    mode: 'pan',
    node: null,
  });
  const projectedRef = useRef<Array<{ node: GraphNode; x: number; y: number; r: number; labelWidth: number }>>([]);

  useEffect(() => {
    for (const node of scene.nodes) {
      const custom = customPositionsRef.current.get(node.id);
      if (custom) {
        node.x = custom.x;
        node.y = custom.y;
      }
    }
    sceneRef.current = scene;
  }, [scene]);

  useEffect(() => {
    selectedRef.current = selectedPath;
    if (!selectedPath) return;
    setExpandedPaths((current) => {
      const next = new Set(current);
      for (const path of graphTracePaths(selectedPath)) {
        if (path !== selectedPath) next.add(path);
      }
      return next.size === current.size ? current : next;
    });
  }, [selectedPath]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const context = canvas.getContext('2d');
    if (!context) return;
    let frame = 0;
    let width = 1;
    let height = 1;
    let dpr = 1;

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      width = Math.max(1, rect.width);
      height = Math.max(1, rect.height);
      const pxWidth = Math.round(width * dpr);
      const pxHeight = Math.round(height * dpr);
      if (canvas.width !== pxWidth || canvas.height !== pxHeight) {
        canvas.width = pxWidth;
        canvas.height = pxHeight;
      }
      context.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    const observer = new ResizeObserver(resize);
    observer.observe(canvas);
    resize();

    const render = (now: number) => {
      drawScene(
        context,
        width,
        height,
        sceneRef.current,
        zoomRef.current,
        panRef.current,
        selectedRef.current,
        draggedNodeRef.current?.id ?? null,
        hoveredNodeIdRef.current,
        projectedRef,
        now,
      );
      frame = requestAnimationFrame(render);
    };
    frame = requestAnimationFrame(render);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, []);

  const pointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const px = event.clientX - rect.left;
    const py = event.clientY - rect.top;

    let hit: { node: GraphNode; x: number; y: number; r: number; labelWidth: number } | null = null;
    let bestDistance = Infinity;
    for (const item of [...projectedRef.current].reverse()) {
      const distance = Math.hypot(item.x - px, item.y - py);
      const hitRadius = Math.max(NODE_CLICK_RADIUS, item.r + 8);
      const onLabel = item.labelWidth > 0 && px >= item.x + 10 && px <= item.x + 10 + item.labelWidth && Math.abs(py - item.y) <= 9;
      if ((distance <= hitRadius || onLabel) && distance < bestDistance) {
        hit = item;
        bestDistance = distance;
      }
    }

    pointerRef.current = {
      x: event.clientX,
      y: event.clientY,
      startX: event.clientX,
      startY: event.clientY,
      dragging: true,
      moved: false,
      mode: hit ? 'node' : 'pan',
      node: hit ? hit.node : null,
    };

    draggedNodeRef.current = hit ? hit.node : null;
    canvas.style.cursor = 'grabbing';
    try { event.currentTarget.setPointerCapture(event.pointerId); } catch {}
  };

  const pointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    if (!pointerRef.current.dragging) {
      const rect = canvas.getBoundingClientRect();
      const px = event.clientX - rect.left;
      const py = event.clientY - rect.top;
      let hovering = false;
      let hoveredNode: GraphNode | null = null;
      for (const item of [...projectedRef.current].reverse()) {
        const distance = Math.hypot(item.x - px, item.y - py);
        const onLabel = item.labelWidth > 0 && px >= item.x + 10 && px <= item.x + 10 + item.labelWidth && Math.abs(py - item.y) <= 9;
        if (distance <= Math.max(NODE_CLICK_RADIUS, item.r + 7) || onLabel) {
          hovering = true;
          hoveredNode = item.node;
          break;
        }
      }
      hoveredNodeIdRef.current = hoveredNode ? hoveredNode.id : null;
      canvas.style.cursor = hovering ? 'grab' : 'default';
      return;
    }

    canvas.style.cursor = 'grabbing';
    const dx = event.clientX - pointerRef.current.x;
    const dy = event.clientY - pointerRef.current.y;
    const totalDistance = Math.hypot(event.clientX - pointerRef.current.startX, event.clientY - pointerRef.current.startY);

    if (!pointerRef.current.moved && totalDistance <= DRAG_THRESHOLD) {
      return;
    }
    pointerRef.current.moved = true;

    if (pointerRef.current.mode === 'node' && draggedNodeRef.current) {
      const node = draggedNodeRef.current;
      const rect = canvas.getBoundingClientRect();
      const width = Math.max(1, rect.width);
      const height = Math.max(1, rect.height);
      const view = getGraphView(sceneRef.current, width, height, zoomRef.current, panRef.current);
      node.x += dx / view.scale;
      node.y += dy / view.scale;
      customPositionsRef.current.set(node.id, { x: node.x, y: node.y });
    } else if (pointerRef.current.mode === 'pan') {
      panRef.current.x += dx;
      panRef.current.y += dy;
    }

    pointerRef.current.x = event.clientX;
    pointerRef.current.y = event.clientY;
  };

  const pointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (canvas) canvas.style.cursor = 'default';

    if (!pointerRef.current.moved) {
      const rect = event.currentTarget.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      let hit: { node: GraphNode; x: number; y: number; r: number; labelWidth: number } | null = null;
      let bestDistance = Infinity;
      for (const item of [...projectedRef.current].reverse()) {
        const distance = Math.hypot(item.x - x, item.y - y);
        const hitRadius = Math.max(NODE_CLICK_RADIUS, item.r + 7);
        const onLabel = item.labelWidth > 0 && x >= item.x + 10 && x <= item.x + 10 + item.labelWidth && Math.abs(y - item.y) <= 9;
        if ((distance <= hitRadius || onLabel) && distance < bestDistance) {
          hit = item;
          bestDistance = distance;
        }
      }
      if (hit?.node.kind === 'group' && hit.node.childCount) {
        const path = hit.node.path;
        setExpandedPaths((current) => {
          const next = new Set(current);
          if (next.has(path)) next.delete(path);
          else next.add(path);
          return next;
        });
      }
      onSelect(hit?.node.path ?? null);
    } else if (pointerRef.current.mode === 'node' && draggedNodeRef.current) {
      onSelect(draggedNodeRef.current.path);
    }

    pointerRef.current.dragging = false;
    pointerRef.current.node = null;
    draggedNodeRef.current = null;
    try { event.currentTarget.releasePointerCapture(event.pointerId); } catch {}
  };

  const wheel = (event: React.WheelEvent<HTMLCanvasElement>) => {
    event.preventDefault();
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const mouseX = event.clientX - rect.left;
    const mouseY = event.clientY - rect.top;
    const width = Math.max(1, rect.width);
    const height = Math.max(1, rect.height);

    const deltaUnit = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? 120 : 1;
    const delta = event.deltaY * deltaUnit;
    const oldZoom = zoomRef.current;
    const next = oldZoom * Math.exp(-delta * 0.0016);
    const newZoom = Math.max(MIN_GRAPH_ZOOM, Math.min(MAX_GRAPH_ZOOM, next));

    if (Math.abs(newZoom - oldZoom) > 0.001) {
      const currentView = getGraphView(sceneRef.current, width, height, oldZoom, panRef.current);
      const nextView = getGraphView(sceneRef.current, width, height, newZoom, { x: 0, y: 0 });
      const zoomRatio = newZoom / oldZoom;
      panRef.current.x = mouseX - nextView.x - (mouseX - currentView.x) * zoomRatio;
      panRef.current.y = mouseY - nextView.y - (mouseY - currentView.y) * zoomRatio;
      zoomRef.current = newZoom;
      setZoomDisplay(Math.round(newZoom * 100));
    }
  };

  const zoomIn = () => {
    const oldZoom = zoomRef.current;
    const newZoom = Math.min(MAX_GRAPH_ZOOM, Number((oldZoom * 1.35).toFixed(2)));
    zoomRef.current = newZoom;
    setZoomDisplay(Math.round(newZoom * 100));
  };

  const zoomOut = () => {
    const oldZoom = zoomRef.current;
    const newZoom = Math.max(MIN_GRAPH_ZOOM, Number((oldZoom / 1.35).toFixed(2)));
    zoomRef.current = newZoom;
    setZoomDisplay(Math.round(newZoom * 100));
  };

  const resetView = () => {
    zoomRef.current = 1;
    panRef.current = { x: 0, y: 0 };
    setZoomDisplay(100);
  };

  const resetLayout = () => {
    customPositionsRef.current.clear();
    const freshScene = buildScene(files, edits, expandedPaths);
    sceneRef.current = freshScene;
    resetView();
  };

  return (
    <>
      <canvas
        ref={canvasRef}
        className="memory-graph-canvas"
        aria-label="Project tree. Click folders to expand or collapse; drag to pan and scroll to zoom."
        onContextMenu={(e) => e.preventDefault()}
        onWheel={wheel}
        onPointerDown={pointerDown}
        onPointerMove={pointerMove}
        onPointerUp={pointerUp}
        onPointerCancel={() => {
          pointerRef.current.dragging = false;
          draggedNodeRef.current = null;
          if (canvasRef.current) canvasRef.current.style.cursor = 'default';
        }}
      />
      <div className="memory-graph-controls" aria-label="Graph navigation controls">
        <button
          type="button"
          className="memory-graph-control-btn"
          title="Zoom in (+)"
          aria-label="Zoom in"
          onClick={zoomIn}
        >+</button>
        <span className="memory-graph-zoom-label" title="Current zoom level">{zoomDisplay}%</span>
        <button
          type="button"
          className="memory-graph-control-btn"
          title="Zoom out (−)"
          aria-label="Zoom out"
          onClick={zoomOut}
        >−</button>
        <button
          type="button"
          className="memory-graph-control-btn"
          title="Reset tree view"
          aria-label="Reset view"
          onClick={resetView}
        >⊙</button>
        <button
          type="button"
          className="memory-graph-control-btn"
          title="Reset node positions"
          aria-label="Reset node positions"
          onClick={resetLayout}
        >↺</button>
      </div>
    </>
  );
}

function buildScene(filesInput: string[], edits: EditedFile[], expandedPaths = new Set([ROOT_NODE_PATH])) {
  const editByPath = new Map(edits.map((item) => [normalizePath(item.path), item]));
  const uniqueFiles = [...new Set([...filesInput, ...edits.map((item) => item.path)].map(normalizePath).filter(Boolean))];
  const prioritized = uniqueFiles
    .map((path) => ({ path, editedAt: Number(editByPath.get(path)?.updatedAt ?? 0) }))
    .sort((a, b) => b.editedAt - a.editedAt || a.path.localeCompare(b.path))
    .slice(0, MAX_GRAPH_FILES);
  const nodes: GraphNode[] = [];
  const edges: GraphEdge[] = [];
  const folderPaths = new Set<string>();

  for (const { path } of prioritized) {
    const segments = pathSegments(path);
    for (let depth = 1; depth < segments.length; depth += 1) {
      folderPaths.add(segments.slice(0, depth).join('/'));
    }
  }

  const root: GraphNode = { id: `group:${ROOT_NODE_PATH}`, path: ROOT_NODE_PATH, label: 'root', kind: 'group', x: 0, y: 0, editedAt: 0 };
  nodes.push(root);

  const sortedFolders = [...folderPaths].sort((a, b) => pathSegments(a).length - pathSegments(b).length || a.localeCompare(b));
  for (const folderPath of sortedFolders) {
    const segments = pathSegments(folderPath);
    nodes.push({
      id: `group:${folderPath}`,
      path: folderPath,
      label: segments.at(-1) || folderPath,
      kind: 'group',
      x: 0,
      y: 0,
      editedAt: 0,
    });
    const parentPath = segments.slice(0, -1).join('/');
    edges.push({ from: parentPath ? `group:${parentPath}` : root.id, to: `group:${folderPath}` });
  }

  for (const { path } of prioritized) {
    const edit = editByPath.get(path);
    const segments = pathSegments(path);
    const parentPath = segments.slice(0, -1).join('/');
    nodes.push({
      id: `file:${path}`,
      path,
      label: leafName(path),
      kind: 'file',
      x: 0,
      y: 0,
      editedAt: Number(edit?.updatedAt ?? 0),
      tool: edit?.tool,
    });
    edges.push({ from: parentPath ? `group:${parentPath}` : root.id, to: `file:${path}` });
  }

  const byId = new Map(nodes.map((node) => [node.id, node]));
  const children = new Map<string, GraphNode[]>();
  for (const edge of edges) {
    const child = byId.get(edge.to)!;
    const siblings = children.get(edge.from) ?? [];
    siblings.push(child);
    children.set(edge.from, siblings);
  }
  for (const siblings of children.values()) {
    siblings.sort((a, b) => Number(b.kind === 'group') - Number(a.kind === 'group') || a.label.localeCompare(b.label));
  }

  const visibleNodes: GraphNode[] = [];
  const visibleEdges: GraphEdge[] = [];
  let row = 0;
  let maxDepth = 0;
  const layout = (node: GraphNode, depth: number) => {
    const descendants = children.get(node.id) ?? [];
    node.x = depth * GRAPH_COLUMN_GAP;
    maxDepth = Math.max(maxDepth, depth);
    visibleNodes.push(node);
    if (node.kind === 'group') {
      node.childCount = descendants.length;
      node.expanded = expandedPaths.has(node.path);
    }
    if (descendants.length && node.expanded) {
      for (const child of descendants) {
        visibleEdges.push({ from: node.id, to: child.id });
        layout(child, depth + 1);
      }
      node.y = (descendants[0].y + descendants[descendants.length - 1].y) / 2;
    } else {
      node.y = row++ * GRAPH_ROW_GAP;
    }
  };
  layout(root, 0);

  return {
    nodes: visibleNodes,
    edges: visibleEdges,
    width: maxDepth * GRAPH_COLUMN_GAP + GRAPH_LABEL_WIDTH,
    height: Math.max(0, row - 1) * GRAPH_ROW_GAP,
  };
}

function drawScene(
  context: CanvasRenderingContext2D,
  width: number,
  height: number,
  scene: ReturnType<typeof buildScene>,
  zoom: number,
  pan: { x: number; y: number },
  selectedPath: string | null,
  draggedNodeId: string | null,
  hoveredNodeId: string | null,
  projectedRef: React.MutableRefObject<Array<{ node: GraphNode; x: number; y: number; r: number; labelWidth: number }>>,
  now: number,
) {
  context.clearRect(0, 0, width, height);
  const view = getGraphView(scene, width, height, zoom, pan);
  const font = `500 ${Math.max(9, Math.min(13, 11 * Math.sqrt(zoom)))}px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif`;
  context.font = font;
  const projected = scene.nodes.map((node) => {
    let label = node.kind === 'group' && node.childCount ? `${node.expanded ? '−' : '+'} ${node.label}` : node.label;
    const maxLabelWidth = Math.max(16, GRAPH_COLUMN_GAP * view.scale - 26);
    if (view.scale < 0.45) label = '';
    else if (context.measureText(label).width > maxLabelWidth) {
      while (label.length > 1 && context.measureText(`${label}…`).width > maxLabelWidth) label = label.slice(0, -1);
      label += '…';
    }
    return { node, x: view.x + node.x * view.scale, y: view.y + node.y * view.scale, label, labelWidth: context.measureText(label).width };
  });
  const byId = new Map(projected.map((item) => [item.node.id, item]));
  const selectedTrace = selectedPath ? graphTracePaths(selectedPath) : null;

  for (const edge of scene.edges) {
    const from = byId.get(edge.from);
    const to = byId.get(edge.to);
    if (!from || !to) continue;
    const highlighted = Boolean(selectedTrace?.has(from.node.path) && selectedTrace?.has(to.node.path));
    const isDraggedEdge = Boolean(draggedNodeId && (from.node.id === draggedNodeId || to.node.id === draggedNodeId));
    context.beginPath();
    const startX = from.x + (from.labelWidth ? from.labelWidth + 14 : 7);
    const elbowX = startX + (to.x - startX) * 0.5;
    context.moveTo(startX, from.y);
    context.lineTo(elbowX, from.y);
    context.lineTo(elbowX, to.y);
    context.lineTo(to.x, to.y);
    context.strokeStyle = isDraggedEdge
      ? 'rgba(121, 215, 255, .85)'
      : highlighted
        ? 'rgba(153, 199, 255, .68)'
        : 'rgba(145, 161, 190, .24)';
    context.lineWidth = isDraggedEdge ? 1.6 : highlighted ? 1.35 : 0.85;
    context.stroke();
  }

  const clickTargets: Array<{ node: GraphNode; x: number; y: number; r: number; labelWidth: number }> = [];
  for (const item of projected) {
    const { node, x, y, label, labelWidth } = item;
    const selected = node.path === selectedPath;
    const isDragged = draggedNodeId === node.id;
    const isHovered = hoveredNodeId === node.id;
    const age = node.editedAt ? Math.max(0, Date.now() - node.editedAt) : Infinity;
    const active = age < ACTIVE_EDIT_MS;
    const baseRadius = node.path === ROOT_NODE_PATH ? 5.2 : node.kind === 'group' ? 4.2 : active ? 4.8 : 2.6;
    const zoomScale = Math.min(2.2, Math.max(0.35, Math.sqrt(view.scale)));
    const radius = baseRadius * zoomScale;

    if (active) {
      const wave = 0.5 + 0.5 * Math.sin(now * 0.006 + hashNumber(node.path));
      const glow = context.createRadialGradient(x, y, radius * 0.3, x, y, radius * (3.3 + wave));
      glow.addColorStop(0, 'rgba(111, 209, 255, .65)');
      glow.addColorStop(1, 'rgba(111, 209, 255, 0)');
      context.fillStyle = glow;
      context.beginPath();
      context.arc(x, y, radius * (3.3 + wave), 0, Math.PI * 2);
      context.fill();
    }
    if (isDragged) {
      context.strokeStyle = 'rgba(121, 215, 255, .95)';
      context.lineWidth = 1.8;
      context.setLineDash([3, 2]);
      context.beginPath();
      context.arc(x, y, radius + 6, 0, Math.PI * 2);
      context.stroke();
      context.setLineDash([]);
    } else if (selected) {
      context.strokeStyle = 'rgba(226, 243, 255, .9)';
      context.lineWidth = 1.2;
      context.beginPath();
      context.arc(x, y, radius + 5, 0, Math.PI * 2);
      context.stroke();
    } else if (isHovered) {
      context.strokeStyle = 'rgba(170, 205, 245, .7)';
      context.lineWidth = 1.0;
      context.beginPath();
      context.arc(x, y, radius + 4, 0, Math.PI * 2);
      context.stroke();
    }

    context.beginPath();
    context.arc(x, y, radius, 0, Math.PI * 2);
    context.fillStyle = node.kind === 'group'
      ? selected || isDragged
        ? 'rgba(218, 229, 246, .96)'
        : node.path === ROOT_NODE_PATH
          ? 'rgba(193, 205, 226, .9)'
          : 'rgba(168, 177, 198, .78)'
      : active
        ? 'rgba(128, 219, 255, .96)'
        : selected || isDragged
          ? 'rgba(230, 245, 255, .96)'
          : 'rgba(181, 198, 224, .78)';
    context.fill();
    clickTargets.push({ node, x, y, r: radius, labelWidth });

    if (label) {
      context.font = font;
      context.fillStyle = selected || isHovered ? 'rgba(235, 241, 249, .96)' : active ? '#79d7ff' : 'rgba(181, 198, 224, .86)';
      context.fillText(label, x + 10, y + 3);
    }

    if (selected || isDragged || isHovered) {
      context.font = '500 11px -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
      const text = displayGraphPath(node.path);
      const metrics = context.measureText(text);
      const boxX = Math.min(width - metrics.width - 18, Math.max(8, x + 10));
      const boxY = Math.max(18, y - 17);
      context.fillStyle = isDragged ? 'rgba(12, 18, 26, .94)' : 'rgba(8, 10, 14, .88)';
      roundedRect(context, boxX - 5, boxY - 12, metrics.width + 10, 20, 5);
      context.fill();
      context.fillStyle = isDragged ? '#79d7ff' : 'rgba(235, 241, 249, .96)';
      context.fillText(text, boxX, boxY + 2);
    }
  }
  projectedRef.current = clickTargets;
}

function getGraphView(scene: ReturnType<typeof buildScene>, width: number, height: number, zoom: number, pan: { x: number; y: number }) {
  const fit = Math.max(0.5, Math.min(1, Math.max(1, width - 48) / scene.width, Math.max(1, height - 76) / (scene.height + GRAPH_ROW_GAP)));
  const scale = fit * zoom;
  return { x: 24 + pan.x, y: height / 2 - 4 - scene.height * scale / 2 + pan.y, scale };
}

function roundedRect(context: CanvasRenderingContext2D, x: number, y: number, width: number, height: number, radius: number) {
  const r = Math.min(radius, width / 2, height / 2);
  context.beginPath();
  context.moveTo(x + r, y);
  context.arcTo(x + width, y, x + width, y + height, r);
  context.arcTo(x + width, y + height, x, y + height, r);
  context.arcTo(x, y + height, x, y, r);
  context.arcTo(x, y, x + width, y, r);
  context.closePath();
}

function normalizePath(value: unknown) { return String(value ?? '').trim().replaceAll('\\', '/').replace(/^\.\//, ''); }
function pathSegments(path: string) { return normalizePath(path).split('/').filter(Boolean); }
function leafName(path: string) { return pathSegments(path).at(-1) || normalizePath(path); }
function displayGraphPath(path: string) { return path === ROOT_NODE_PATH ? 'root' : `root/${normalizePath(path)}`; }
function graphTracePaths(path: string) {
  const trace = new Set<string>([ROOT_NODE_PATH]);
  if (path === ROOT_NODE_PATH) return trace;
  const segments = pathSegments(path);
  for (let depth = 1; depth <= segments.length; depth += 1) trace.add(segments.slice(0, depth).join('/'));
  return trace;
}
function hashNumber(value: string) { let hash = 2166136261; for (let index = 0; index < value.length; index += 1) { hash ^= value.charCodeAt(index); hash = Math.imul(hash, 16777619); } return hash >>> 0; }
function relativeTime(value: number) { const delta = Date.now() - Number(value || 0); if (!value) return 'recently'; if (delta < 5_000) return 'just now'; if (delta < 60_000) return `${Math.max(1, Math.floor(delta / 1000))}s ago`; if (delta < 3_600_000) return `${Math.floor(delta / 60_000)}m ago`; return `${Math.floor(delta / 3_600_000)}h ago`; }
function humanTool(value: string) { return value.replace(/^cuppet_/, '').replace(/^tst_/, 'TST ').replace(/^workspace_/, '').replaceAll('_', ' ').replace(/\b\w/g, (match) => match.toUpperCase()); }
function cleanError(error: unknown) { return error instanceof Error ? error.message : String(error ?? 'TST graph unavailable'); }

