import type { MessageActivity, RuntimeEvent } from '../types';

const MAX_ITEMS_PER_MESSAGE = 120;

export type TranscriptReasoning = {
  id: string;
  type: 'reasoning';
  text: string;
  sequence: number;
  endSequence?: number;
  kind?: 'commentary';
  startedAt?: number;
  completedAt?: number;
};

export type TranscriptTool = {
  id: string;
  type: 'tool';
  status: 'running' | 'complete' | 'error';
  tool: string;
  argumentsJson: string;
  details?: string;
  sequence: number;
};

export type TranscriptStatus = { id: string; type: 'status'; text: string; sequence: number };
export type TranscriptItem = TranscriptReasoning | TranscriptTool | TranscriptStatus;
export type ContextUsage = { usedTokens: number; windowTokens: number; sequence: number; estimated?: boolean };
export type TranscriptMessageState = { items: TranscriptItem[]; preview: string; contextUsage?: ContextUsage };
export type TranscriptState = Record<string, TranscriptMessageState>;

export function hydrateTranscript(rows: MessageActivity[] = []): TranscriptState {
  let state: TranscriptState = {};
  for (const row of rows.slice().sort(compareActivityRows)) {
    state = reduceTranscriptEvent(state, {
      type: 'runtime.activity',
      messageId: row.messageId,
      source: row.source,
      sequence: row.sequence,
      createdAt: row.createdAt,
      activity: row.activity,
    });
  }
  return state;
}

export function mergeTranscriptState(live: TranscriptState, durable: TranscriptState): TranscriptState {
  const next: TranscriptState = { ...live };
  for (const [messageId, persisted] of Object.entries(durable)) {
    const current = live[messageId];
    if (!current) {
      next[messageId] = persisted;
      continue;
    }
    const byId = new Map<string, TranscriptItem>();
    for (const item of persisted.items) byId.set(item.id, item);
    for (const item of current.items) {
      const durableItem = byId.get(item.id);
      if (!durableItem) {
        byId.set(item.id, item);
        continue;
      }
      if (item.type === 'reasoning' && durableItem.type === 'reasoning') {
        const liveEnd = item.endSequence ?? item.sequence;
        const durableEnd = durableItem.endSequence ?? durableItem.sequence;
        const latest = liveEnd > durableEnd || item.text.length > durableItem.text.length ? item : durableItem;
        byId.set(item.id, { ...latest, completedAt: latest.completedAt ?? item.completedAt ?? durableItem.completedAt });
      } else if (item.type === 'tool' && durableItem.type === 'tool') {
        if (item.status !== 'running' && durableItem.status === 'running') byId.set(item.id, item);
      }
    }
    const contextUsage = current.contextUsage && (!persisted.contextUsage || current.contextUsage.sequence >= persisted.contextUsage.sequence)
      ? current.contextUsage : persisted.contextUsage;
    next[messageId] = {
      items: boundItems(orderedTranscriptItems([...byId.values()])),
      preview: current.preview,
      ...(contextUsage ? { contextUsage } : {}),
    };
  }
  return next;
}

export function reduceTranscriptEvent(state: TranscriptState, event: RuntimeEvent): TranscriptState {
  if (!event || typeof event !== 'object') return state;
  const messageId = text(event.messageId);
  if (!messageId) return state;
  const createdAt = Number(event.createdAt) || Date.now();

  if (event.type === 'message.preview') {
    const content = typeof event.content === 'string' ? event.content : '';
    return updateMessageState(state, messageId, (current) => {
      const items = content ? completeReasoning(current.items, createdAt) : current.items;
      if (current.preview === content && items === current.items) return current;
      return { ...current, items, preview: content };
    });
  }

  if (event.type === 'message.delta' || event.type === 'message.completed') {
    return updateMessageState(state, messageId, (current) => {
      const items = completeReasoning(current.items, createdAt);
      return current.preview || items !== current.items ? { ...current, items, preview: '' } : current;
    });
  }

  if (event.type !== 'runtime.activity') return state;
  const activity = record(event.activity);
  const activityType = text(activity.type);
  if (!activityType) return state;
  const sequence = finiteSequence(event.sequence);

  if (event.source === 'provider' && activityType === 'activity.text.delta') {
    return updateMessageState(state, messageId, (current) => {
      const items = completeReasoning(current.items, createdAt);
      return items === current.items ? current : { ...current, items };
    });
  }

  if (event.source === 'provider' && activityType === 'activity.warning' && activity.code === 'provider_retry') {
    const message = text(activity.message);
    if (!message) return state;
    return updateMessageState(state, messageId, (current) => {
      const resolvedSequence = sequence ?? nextSequence(current.items);
      const id = `status-${resolvedSequence}`;
      if (current.items.some((item) => item.id === id)) return current;
      return { ...current, items: boundItems([...current.items, { id, type: 'status', text: message, sequence: resolvedSequence }]) };
    });
  }

  if (event.source === 'provider' && activityType === 'activity.usage') {
    const usage = record(activity.contextUsage);
    const usedTokens = usage.usedTokens;
    const windowTokens = usage.windowTokens;
    if (!Number.isFinite(usedTokens) || usedTokens < 0 || !Number.isFinite(windowTokens) || windowTokens <= 0) return state;
    return updateMessageState(state, messageId, (current) => {
      const usageSequence = sequence ?? (current.contextUsage?.sequence ?? -1) + 1;
      if (current.contextUsage && usageSequence < current.contextUsage.sequence) return current;
      return { ...current, contextUsage: { usedTokens, windowTokens, sequence: usageSequence, ...(usage.estimated === true ? { estimated: true } : {}) } };
    });
  }

  if (event.source === 'provider' && activityType === 'activity.reasoning.delta') {
    const segment = typeof activity.text === 'string' ? activity.text : '';
    if (!segment) return state;
    return updateMessageState(state, messageId, (current) => {
      const items = appendReasoning(current.items, segment, sequence, {
        startedAt: Number(activity.startedAt) || createdAt,
        ...(Number(activity.completedAt) > 0 ? { completedAt: Number(activity.completedAt) } : {}),
        ...(activity.kind === 'commentary' ? { kind: 'commentary' as const } : {}),
      });
      return items === current.items ? current : { ...current, items };
    });
  }

  if ((event.source === 'execution' && activityType.startsWith('activity.tool.')) || (event.source === 'provider' && activityType.startsWith('activity.tool.'))) {
    return updateMessageState(state, messageId, (current) => ({
      ...current,
      items: updateTool(completeReasoning(current.items, createdAt), activity, sequence),
    }));
  }

  return state;
}

export function orderedTranscriptItems(items: TranscriptItem[] = []) {
  return items
    .map((item, index) => ({ item, index }))
    .sort((a, b) => compareSequence(a.item.sequence, b.item.sequence) || a.index - b.index)
    .map(({ item }) => item);
}

function appendReasoning(items: TranscriptItem[], segment: string, sequence: number | null, timing: Pick<TranscriptReasoning, 'kind' | 'startedAt' | 'completedAt'>): TranscriptItem[] {
  const ordered = orderedTranscriptItems(items);
  const last = ordered.at(-1);
  if (last?.type === 'reasoning' && last.kind === timing.kind && !last.completedAt && reasoningCanMerge(last, sequence)) {
    const textValue = mergeReasoningText(last.text, segment);
    if (textValue === last.text) return items;
    return boundItems(items.map((item) => item.id === last.id && item.type === 'reasoning' ? {
      ...item,
      text: textValue,
      endSequence: sequence ?? item.endSequence ?? item.sequence,
      ...(timing.completedAt ? { completedAt: timing.completedAt } : {}),
    } : item));
  }
  const resolvedSequence = sequence ?? nextSequence(items);
  return boundItems([
    ...completeReasoning(items, timing.startedAt ?? Date.now()),
    {
      id: `reason-${resolvedSequence}-${items.length}`,
      type: 'reasoning',
      text: segment,
      sequence: resolvedSequence,
      endSequence: resolvedSequence,
      ...timing,
    },
  ]);
}

function completeReasoning(items: TranscriptItem[], completedAt: number): TranscriptItem[] {
  if (!items.some((item) => item.type === 'reasoning' && !item.completedAt)) return items;
  return items.map((item) => item.type === 'reasoning' && !item.completedAt
    ? { ...item, completedAt: Math.max(item.startedAt ?? completedAt, completedAt) }
    : item);
}

function reasoningCanMerge(last: TranscriptReasoning, sequence: number | null) {
  if (sequence === null) return true;
  const end = finiteSequence(last.endSequence) ?? finiteSequence(last.sequence);
  return end === null || sequence >= end;
}

function updateTool(items: TranscriptItem[], activity: Record<string, any>, sequence: number | null): TranscriptItem[] {
  const id = text(activity.executionId) || text(activity.callId) || `tool-${sequence ?? nextSequence(items)}`;
  const toolName = text(activity.tool) || 'agent-tool';
  const existingIndex = items.findIndex((item) => item.type === 'tool' && (
    item.id === id || (item.status === 'running' && item.tool === toolName)
  ));
  const existing = existingIndex >= 0 ? items[existingIndex] as TranscriptTool : null;
  const tool = toolName || existing?.tool || 'agent-tool';
  const argumentsJson = typeof activity.argumentsJson === 'string' && activity.argumentsJson !== '{}'
    ? activity.argumentsJson
    : existing?.argumentsJson ?? (typeof activity.argumentsJson === 'string' ? activity.argumentsJson : '{}');
  const closed = activity.type === 'activity.tool.closed';
  const status: TranscriptTool['status'] = closed ? (activity.status === 'success' ? 'complete' : 'error') : 'running';
  const patch: TranscriptTool = {
    id: existing?.id ?? id,
    type: 'tool',
    status,
    tool,
    argumentsJson,
    sequence: existing?.sequence ?? sequence ?? nextSequence(items),
    ...(typeof activity.details === 'string' && activity.details ? { details: activity.details } : existing?.details ? { details: existing.details } : {}),
  };
  if (existingIndex < 0) return boundItems([...items, patch]);
  const next = [...items];
  next[existingIndex] = patch;
  return boundItems(next);
}

function updateMessageState(state: TranscriptState, messageId: string, updater: (value: TranscriptMessageState) => TranscriptMessageState) {
  const current = state[messageId] ?? { items: [], preview: '' };
  const next = updater(current);
  if (next === current) return state;
  return { ...state, [messageId]: next };
}

function boundItems(items: TranscriptItem[]) {
  if (items.length <= MAX_ITEMS_PER_MESSAGE) return items;
  return orderedTranscriptItems(items).slice(-MAX_ITEMS_PER_MESSAGE);
}

function mergeReasoningText(previous: string, incoming: string) {
  if (!previous) return incoming;
  if (!incoming) return previous;
  if (incoming.startsWith(previous)) return incoming;
  return `${previous}${incoming}`;
}

function nextSequence(items: TranscriptItem[]) {
  let max = -1;
  for (let index = 0; index < items.length; index += 1) {
    const sequence = finiteSequence(items[index]?.sequence);
    max = Math.max(max, sequence ?? index);
  }
  return max + 1;
}

function compareActivityRows(left: MessageActivity, right: MessageActivity) {
  const messageCompare = text(left.messageId).localeCompare(text(right.messageId));
  if (messageCompare) return messageCompare;
  const sequenceCompare = compareSequence(left.sequence, right.sequence);
  if (sequenceCompare) return sequenceCompare;
  return Number(left.createdAt ?? 0) - Number(right.createdAt ?? 0);
}

function compareSequence(left: unknown, right: unknown) {
  const a = finiteSequence(left);
  const b = finiteSequence(right);
  if (a === null && b === null) return 0;
  if (a === null) return 1;
  if (b === null) return -1;
  return a - b;
}

function finiteSequence(value: unknown) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function text(value: unknown) {
  return typeof value === 'string' ? value.trim() : '';
}

function record(value: unknown): Record<string, any> {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, any> : {};
}

export function formatWorkedDuration(ms: number): string {
  const totalSeconds = Math.max(1, Math.round(ms / 1000));
  if (totalSeconds < 60) {
    return `${totalSeconds}s`;
  }
  const totalMinutes = Math.floor(totalSeconds / 60);
  if (totalMinutes < 60) {
    return `${totalMinutes}m ${totalSeconds % 60}s`;
  }
  const totalHours = Math.floor(totalMinutes / 60);
  return `${totalHours}h ${totalMinutes % 60}m`;
}

