import { useEffect, useMemo, useRef, useState } from 'react';
import type { ProviderModelCatalog, ProviderSettings } from '../types';
import { notifyProviderSettingsChanged, PROVIDER_CATALOG_INVALID_EVENT } from './provider-settings-events';
import { cachedModelCatalog, cachedProviderCatalog, isProviderCatalogStale, loadModelCatalog, CATALOG_FRESH_MS } from './model-catalog-cache';
import { orderPinnedModels, togglePinnedModel, usePinnedModels } from './model-pins';
import {
  hydrateClientProviderSettings,
  refreshClientProviderSettings,
  useClientProviderSettings,
} from './client-provider-state';

type ModelOption = {
  id: string;
  label: string;
  description?: string;
};

type PickerStage = 'models' | 'efforts';
type ModelSlot = 'primary' | 'secondary';
type SettingsWithSecondaryAuto = ProviderSettings & { secondaryAuto?: boolean };

type Props = {
  disabled?: boolean;
  slot?: ModelSlot;
  surface?: 'composer' | 'settings';
  onChange?: (settings: ProviderSettings) => void;
};

const EMPTY_ADVERTISED: ProviderModelCatalog = { providerID: '', available: false, source: 'none', models: [], defaultModel: null };

export function ModelPicker({ disabled = false, slot = 'primary', surface = 'composer', onChange }: Props) {
  const root = useRef<HTMLDivElement | null>(null);
  const [open, setOpen] = useState(false);
  const [stage, setStage] = useState<PickerStage>('models');
  const [busy, setBusy] = useState(false);
  const settings = useClientProviderSettings();
  const [advertised, setAdvertised] = useState<ProviderModelCatalog>(() => settings ? cachedModelCatalog(settings) ?? cachedProviderCatalog(settings) ?? EMPTY_ADVERTISED : EMPTY_ADVERTISED);
  const [error, setError] = useState('');
  const catalogRequest = useRef(0);

  const refreshCatalog = async (next: ProviderSettings, refresh = false) => {
    const providerID = next.primary?.providerID || next.providerID || '';
    const request = ++catalogRequest.current;
    setError('');
    const catalog = await loadModelCatalog(next, { refresh });
    if (request !== catalogRequest.current) return catalog;
    // Discovery can clear an unsupported saved effort in the host settings store.
    await refreshClientProviderSettings();
    setAdvertised(catalog.providerID === providerID ? (catalog.error && !catalog.models.length ? cachedModelCatalog(next) ?? catalog : catalog) : EMPTY_ADVERTISED);
    if (catalog.error && !catalog.models.length) setError(catalog.error);
    return catalog;
  };

  const refresh = async () => {
    const next = settings ?? await refreshClientProviderSettings();
    await refreshCatalog(next);
    return next;
  };

  const acceptSettings = (next: ProviderSettings) => {
    hydrateClientProviderSettings(next);
    onChange?.(next);
    notifyProviderSettingsChanged();
    return next;
  };

  useEffect(() => {
    if (!settings) return;
    setAdvertised(cachedModelCatalog(settings) ?? cachedProviderCatalog(settings) ?? EMPTY_ADVERTISED);
    void refreshCatalog(settings).catch((value) => setError(message(value)));
  }, [settings?.primary?.providerID, settings?.providerID, settings?.baseUrl]);

  useEffect(() => {
    if (!settings) return;
    const revalidate = (force: boolean) => {
      if (!force && !isProviderCatalogStale(settings)) return;
      void refreshCatalog(settings, force).catch((value) => setError(message(value)));
    };
    const onFocus = () => revalidate(false);
    const onInvalidated = () => revalidate(true);
    const onVisible = () => { if (document.visibilityState === 'visible') revalidate(false); };
    const timer = window.setInterval(() => revalidate(false), CATALOG_FRESH_MS);
    window.addEventListener('focus', onFocus);
    window.addEventListener(PROVIDER_CATALOG_INVALID_EVENT, onInvalidated);
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      window.clearInterval(timer);
      window.removeEventListener('focus', onFocus);
      window.removeEventListener(PROVIDER_CATALOG_INVALID_EVENT, onInvalidated);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [settings]);

  useEffect(() => {
    if (!open) return;
    const close = (event: PointerEvent) => {
      if (!root.current?.contains(event.target as Node)) {
        setOpen(false);
        setStage('models');
      }
    };
    document.addEventListener('pointerdown', close);
    return () => document.removeEventListener('pointerdown', close);
  }, [open]);

  const providerID = settings?.primary?.providerID || settings?.providerID || '';
  const pinnedModels = usePinnedModels(providerID);
  const providerPreset = settings?.presets?.find((item) => item.id === providerID);
  const providerLabel = providerPreset?.label || providerID || 'Provider';
  const configuredModel = slot === 'secondary'
    ? settings?.secondary?.modelID || settings?.primary?.modelID || ''
    : settings?.primary?.modelID || '';
  const secondaryAuto = slot === 'secondary' && (settings as SettingsWithSecondaryAuto | null)?.secondaryAuto !== false;

  const options = useMemo<ModelOption[]>(() => {
    const custom = (settings?.customModels ?? []).filter((item) => item.providerID === providerID);
    const output: ModelOption[] = [];
    const seen = new Set<string>();
    const add = (id?: string, label?: string, description?: string) => {
      const value = String(id ?? '').trim();
      if (!value || seen.has(value)) return;
      seen.add(value);
      output.push({ id: value, label: label || value, ...(description ? { description } : {}) });
    };

    const liveModels = advertised.providerID === providerID ? advertised.models : [];
    const presetDefaultID = String(providerPreset?.model ?? '').trim();
    const presetDefaultEntry = providerPreset?.models?.find((item) => item.id === presetDefaultID);
    if (presetDefaultID && advertised.defaultModel && !liveModels.some((item) => item.id === presetDefaultID) && !presetDefaultEntry) {
      const resolvedDefault = liveModels.find((item) => item.id === advertised.defaultModel);
      add(
        presetDefaultID,
        resolvedDefault ? `${resolvedDefault.label || resolvedDefault.id} · Default` : `${providerLabel} default`,
        `Follow the default model selected by your ${providerLabel} account or configuration.`,
      );
    }
    const fallbackModels = liveModels.length ? [] : providerPreset?.models ?? [];
    for (const model of liveModels) add(model.id, model.label, model.description);
    for (const model of fallbackModels) add(model.id, model.label, model.description);
    for (const model of custom) add(model.modelID, model.modelID, 'Custom model · validated in Provider settings.');
    for (const model of settings?.models ?? []) {
      if (model.providerID !== providerID) continue;
      add(model.modelID, model.name);
    }
    add(configuredModel, configuredModel);
    if (providerID === 'opencode') {
      output.sort((a, b) => Number(/^opencode(?:-go)?\//.test(b.id)) - Number(/^opencode(?:-go)?\//.test(a.id)));
    }
    return orderPinnedModels(output, pinnedModels);
  }, [advertised, configuredModel, providerID, providerLabel, providerPreset?.model, providerPreset?.models, settings?.customModels, settings?.models, pinnedModels]);

  const effortState = modelEffortState(providerID, configuredModel, settings, advertised);
  const effortOptions = effortState.options;
  const explicitEffort = selectedEffort(slot, providerID, settings);
  const defaultEffort = effortState.defaultEffort?.trim() || '';
  const defaultInOptions = Boolean(defaultEffort && effortOptions.some((item) => item.toLowerCase() === defaultEffort.toLowerCase()));
  const resolvedModelLabel = useMemo(() => {
    const presetDefaultID = String(providerPreset?.model ?? '').trim();
    if (presetDefaultID && configuredModel === presetDefaultID && advertised.defaultModel) {
      return advertised.models.find((item) => item.id === advertised.defaultModel)?.label || advertised.defaultModel;
    }
    return options.find((item) => item.id === configuredModel)?.label || configuredModel || 'Select model';
  }, [advertised.defaultModel, advertised.models, configuredModel, options, providerPreset?.model]);
  const displayModel = secondaryAuto ? 'Auto' : resolvedModelLabel;

  const chooseAuto = async () => {
    if (slot !== 'secondary' || secondaryAuto) {
      setOpen(false);
      setStage('models');
      return;
    }
    setOpen(false);
    setStage('models');
    if (settings) {
      acceptSettings({ ...settings, secondaryAuto: true } as any);
    }
    setBusy(true);
    setError('');
    try {
      const current = settings ?? await refreshClientProviderSettings();
      const currentProvider = current.primary?.providerID || current.providerID || '';
      const primaryModel = current.primary?.modelID || '';
      if (!currentProvider || !primaryModel) throw new Error('Configure a primary model before using automatic secondary selection.');
      const next = await window.cuppet.settings.save({
        providerID: currentProvider,
        baseUrl: current.baseUrl || '',
        model: primaryModel,
        backgroundModel: current.secondary?.modelID || primaryModel,
        primaryEffort: selectedEffort('primary', currentProvider, current),
        secondaryEffort: '',
        secondaryAuto: true,
      });
      acceptSettings(next);
    } catch (value) {
      setError(message(value));
    } finally {
      setBusy(false);
    }
  };

  const chooseModel = async (modelID: string) => {
    const id = modelID.trim();
    if (!id) return;
    setBusy(true);
    setError('');
    try {
      const current = settings ?? await refreshClientProviderSettings();
      const currentProvider = providerID || current.providerID;
      if (!currentProvider) throw new Error('Configure a provider before selecting a model.');

      let candidateAdvertised = cachedModelCatalog(current, id) ?? advertised;
      const refreshCandidate = candidateAdvertised.providerID !== currentProvider
        || (candidateAdvertised.modelDependentSettings === true && candidateAdvertised.configuredModel !== id);
      if (refreshCandidate) {
        const refreshed = await loadModelCatalog(current, { model: id });
        if (refreshed.providerID !== currentProvider) throw new Error('Provider changed while refreshing model capabilities.');
        if (refreshed.error && !refreshed.models.length) throw new Error(refreshed.error);
        candidateAdvertised = refreshed;
        setAdvertised(refreshed);
      }

      const nextEffortState = modelEffortState(currentProvider, id, current, candidateAdvertised);
      if (id !== configuredModel || secondaryAuto) {
        const nextEffort = effortForModel(slot, currentProvider, id, current, candidateAdvertised);
        const primaryModel = slot === 'primary' ? id : current.primary?.modelID || id;
        const secondaryModel = slot === 'secondary' ? id : current.secondary?.modelID || id;
        const optimistic: ProviderSettings = {
          ...current,
          ...(slot === 'primary' ? { primaryEffort: nextEffort } : {}),
          primary: {
            ...current.primary,
            modelID: primaryModel,
            providerID: currentProvider,
            variant: slot === 'primary' ? nextEffort : current.primary?.variant,
          },
          secondary: {
            ...current.secondary,
            modelID: secondaryModel,
            providerID: currentProvider,
            variant: slot === 'secondary' ? nextEffort : current.secondary?.variant,
          },
          ...(slot === 'secondary' ? { secondaryAuto: false } : {}),
        };
        acceptSettings(optimistic);

        if (slot === 'primary' && nextEffortState.options.length > 0) {
          setStage('efforts');
          setOpen(true);
        } else {
          setOpen(false);
          setStage('models');
        }

        const next = await window.cuppet.settings.save({
          providerID: currentProvider,
          baseUrl: current.baseUrl || '',
          model: primaryModel,
          backgroundModel: secondaryModel,
          primaryEffort: slot === 'primary' ? nextEffort : selectedEffort('primary', currentProvider, current),
          secondaryEffort: slot === 'secondary' ? nextEffort : selectedEffort('secondary', currentProvider, current),
          ...(slot === 'secondary' ? { secondaryAuto: false } : {}),
        });
        acceptSettings(next);
      } else {
        if (slot === 'primary' && nextEffortState.options.length > 0) {
          setStage('efforts');
          setOpen(true);
        } else {
          setOpen(false);
          setStage('models');
        }
      }
    } catch (value) {
      setError(message(value));
    } finally {
      setBusy(false);
    }
  };

  const chooseEffort = async (effort: string) => {
    const value = effort === 'default' ? '' : effort.trim();
    if (!configuredModel || (value && !effortOptions.includes(value))) return;
    if (value === explicitEffort || (!value && !explicitEffort)) {
      setOpen(false);
      setStage('models');
      return;
    }
    setOpen(false);
    setStage('models');
    if (settings) {
      const optimistic: ProviderSettings = {
        ...settings,
        primaryEffort: value,
        primary: {
          ...settings.primary,
          variant: value,
        },
      };
      acceptSettings(optimistic);
    }
    setBusy(true);
    setError('');
    try {
      const current = settings ?? await refreshClientProviderSettings();
      const currentProvider = current.primary?.providerID || current.providerID || '';
      if (!currentProvider) throw new Error('Configure a provider before selecting reasoning effort.');
      const saved = await window.cuppet.settings.save({
        providerID: currentProvider,
        baseUrl: current.baseUrl || '',
        model: current.primary?.modelID || configuredModel,
        backgroundModel: current.secondary?.modelID || current.primary?.modelID || configuredModel,
        primaryEffort: value,
        secondaryEffort: selectedEffort('secondary', currentProvider, current),
      });
      acceptSettings(saved);
    } catch (value) {
      setError(message(value));
    } finally {
      setBusy(false);
    }
  };

  const toggle = async () => {
    if (disabled || busy) return;
    if (open) {
      setOpen(false);
      setStage('models');
      return;
    }
    setStage('models');
    setOpen(true);
    setError('');
    try { await refresh(); }
    catch (value) { setError(message(value)); }
  };

  const slotLabel = slot === 'secondary' ? 'secondary' : 'primary';
  // Renderer contract: the default composer trigger resolves to aria-label="Select model".
  const triggerAriaLabel = surface === 'composer' && slot === 'primary' ? 'Select model' : `Select ${slotLabel} model`;
  const triggerTitle = secondaryAuto
    ? `Secondary model: Auto · currently ${resolvedModelLabel}`
    : configuredModel ? `${slot === 'secondary' ? 'Secondary model' : 'Model'}: ${displayModel}` : triggerAriaLabel;

  return (
    <div className={`model-picker${surface === 'settings' ? ' settings-model-picker' : ''}${open ? ' open' : ''}`} ref={root}>
      <button
        type="button"
        className="model-picker-trigger"
        aria-label={triggerAriaLabel}
        aria-haspopup="listbox"
        aria-expanded={open}
        disabled={disabled || busy}
        title={triggerTitle}
        onClick={() => void toggle()}
      >
        <span className="model-picker-name">{displayModel}</span>
        <svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m4.5 6 3.5 3.5L11.5 6" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" /></svg>
      </button>

      {open && (
        <div className="model-picker-menu" role="listbox" aria-label={stage === 'models' ? `${slotLabel} models` : 'Reasoning effort'}>
          {stage === 'models' ? (
            <>
              <div className="model-picker-provider">{slot === 'secondary' ? `${providerLabel} · Secondary models` : `${providerLabel} · Models`}</div>
              {slot === 'secondary' && (
                <button
                  type="button"
                  role="option"
                  aria-selected={secondaryAuto}
                  className={`model-picker-option${secondaryAuto ? ' selected' : ''}`}
                  disabled={busy}
                  onClick={() => void chooseAuto()}
                >
                  <strong>Auto</strong>
                  {secondaryAuto && <span className="model-picker-check" aria-hidden="true">✓</span>}
                </button>
              )}
              {options.length > 0 ? options.map((option) => {
                const selected = !secondaryAuto && option.id === configuredModel;
                const pinned = pinnedModels.includes(option.id);
                return (
                  <div className="model-picker-row" key={option.id}>
                  <button
                    type="button"
                    role="option"
                    aria-selected={selected}
                    className={`model-picker-option${selected ? ' selected' : ''}`}
                    disabled={busy}
                    onClick={() => void chooseModel(option.id)}
                  >
                    <strong>{pinned && <ModelPinIcon pinned className="model-picker-pinned-mark" />}{option.label}</strong>
                    {option.description && <small>{option.description}</small>}
                    {selected && <span className="model-picker-check" aria-hidden="true">✓</span>}
                  </button>
                  {surface === 'settings' && <button
                    type="button"
                    className="model-picker-pin-button"
                    aria-label={`${pinned ? 'Unpin' : 'Pin'} ${option.label}`}
                    title={`${pinned ? 'Unpin' : 'Pin'} model`}
                    aria-pressed={pinned}
                    disabled={busy}
                    onClick={() => togglePinnedModel(providerID, option.id)}
                  ><ModelPinIcon pinned={pinned} /></button>}
                  </div>
                );
              }) : <div className="model-picker-empty">No models advertised by this provider.</div>}
            </>
          ) : (
            <>
              <button type="button" className="model-picker-back" onClick={() => setStage('models')}>← Models</button>
              <div className="model-picker-provider" title={displayModel}>{displayModel} · Effort</div>
              {!defaultInOptions && (
                <button
                  type="button"
                  role="option"
                  aria-selected={!explicitEffort || explicitEffort.toLowerCase() === 'default'}
                  className={`model-picker-effort-option${(!explicitEffort || explicitEffort.toLowerCase() === 'default') ? ' selected' : ''}`}
                  onClick={() => void chooseEffort('default')}
                >
                  <span>Default{defaultEffort ? ` · ${formatEffort(defaultEffort)}` : ''}</span>
                  {(!explicitEffort || explicitEffort.toLowerCase() === 'default') && <span aria-hidden="true">✓</span>}
                </button>
              )}
              {effortOptions.map((effort) => {
                const isDefault = defaultInOptions && effort.toLowerCase() === defaultEffort.toLowerCase();
                const isSelected = isDefault
                  ? (!explicitEffort || explicitEffort.toLowerCase() === 'default' || explicitEffort.toLowerCase() === effort.toLowerCase())
                  : explicitEffort.toLowerCase() === effort.toLowerCase();
                return (
                  <button
                    type="button"
                    role="option"
                    aria-selected={isSelected}
                    className={`model-picker-effort-option${isSelected ? ' selected' : ''}`}
                    key={effort}
                    onClick={() => void chooseEffort(isDefault ? 'default' : effort)}
                  >
                    <span>{formatEffort(effort)}{isDefault ? ' · Default' : ''}</span>
                    {isSelected && <span aria-hidden="true">✓</span>}
                  </button>
                );
              })}
            </>
          )}
          {error && <div className="model-picker-error" role="status">{error}</div>}
        </div>
      )}
    </div>
  );
}

function ModelPinIcon({ pinned, className }: { pinned: boolean; className?: string }) {
  return <svg className={className} viewBox="0 0 16 16" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round">
    <path d="m9 2 5 5-3 1v3l-1 1-6-6 1-1h3l1-3Z" fill={pinned ? 'currentColor' : 'none'} />
    <path d="m6 10-4 4" />
  </svg>;
}

function modelEffortState(providerID: string, modelID: string, settings: ProviderSettings | null, advertised: ProviderModelCatalog) {
  if (settings && (advertised.providerID !== providerID || advertised.configuredModel !== modelID)) {
    advertised = cachedModelCatalog(settings, modelID) ?? advertised;
  }
  const exactLiveSnapshot = advertised.available === true && !advertised.error && advertised.providerID === providerID
    && advertised.modelDependentSettings === true
    && advertised.configuredModel === modelID;
  if (exactLiveSnapshot) {
    const rawOptions = advertised.reasoning?.options?.map((item) => item.id) ?? [];
    const currentValue = advertised.reasoning?.currentValue || '';
    return {
      options: rawOptions.filter((id) => id.toLowerCase() !== 'default'),
      defaultEffort: currentValue.toLowerCase() !== 'default' ? currentValue : '',
    };
  }
  if (advertised.providerID === providerID && advertised.modelDependentSettings === true) {
    return { options: [], defaultEffort: '' };
  }
  const model = settings?.models?.find((item) => item.providerID === providerID && item.modelID === modelID);
  const rawVariants = model?.variants ?? [];
  return {
    options: rawVariants.filter((id) => id.toLowerCase() !== 'default'),
    defaultEffort: '',
  };
}

function selectedEffort(slot: ModelSlot, providerID: string, settings: ProviderSettings | null) {
  if (slot === 'primary' && settings?.primaryEffort) return String(settings.primaryEffort).trim();
  const selection = slot === 'secondary' ? settings?.secondary : settings?.primary;
  return String(selection?.variant ?? '').trim();
}

function effortForModel(slot: ModelSlot, providerID: string, modelID: string, settings: ProviderSettings, advertised: ProviderModelCatalog) {
  const currentEffort = selectedEffort(slot, providerID, settings);
  const state = modelEffortState(providerID, modelID, settings, advertised);
  if (currentEffort && state.options.includes(currentEffort)) return currentEffort;
  return '';
}

function formatEffort(value: string) {
  const effort = value.trim();
  if (!effort) return 'Default';
  const lower = effort.toLowerCase();
  if (lower === 'xhigh' || lower === 'x-high' || lower === 'extra-high' || lower === 'extra_high') {
    return 'Extra High';
  }
  return effort.split(/[-_]/g).filter(Boolean).map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(' ');
}

function message(value: unknown) {
  return value instanceof Error ? value.message : String(value ?? 'Unable to load models.');
}
